<?php
declare(strict_types=1);
require_once __DIR__.'/refunds.php';

function tuman_report_filter(PDO $db,int $teacherId,array $input): array { $from=trim((string)($input['from']??date('Y-m-01')));$to=trim((string)($input['to']??date('Y-m-t')));if(!tuman_invoice_valid_date($from)||!tuman_invoice_valid_date($to)||$from>$to)throw new InvalidArgumentException('Choose a valid date range.');$assignment=null;$raw=trim((string)($input['assignment_id']??''));if($raw!==''){$assignment=filter_var($raw,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$assignment||tuman_teacher_student($db,$teacherId,(int)$assignment)===null)throw new InvalidArgumentException('Student is unavailable.');}return ['from'=>$from,'to'=>$to,'assignment_id'=>$assignment]; }
function tuman_report_amounts(PDO $db,string $sql,array $params): array {$s=$db->prepare($sql);$s->execute($params);return $s->fetchAll();}
function tuman_teacher_income_report(PDO $db,int $teacherId,array $f): array {$where='ts.teacher_user_id=:teacher AND p.payment_date BETWEEN :from AND :to';$params=['teacher'=>$teacherId,'from'=>$f['from'],'to'=>$f['to']];if($f['assignment_id']??null){$where.=' AND i.teacher_student_id=:assignment';$params['assignment']=$f['assignment_id'];}$payments=tuman_report_amounts($db,"SELECT p.currency_code,SUM(p.amount) amount FROM tmn_payments p INNER JOIN tmn_invoices i ON i.id=p.invoice_id INNER JOIN tmn_teacher_students ts ON ts.id=i.teacher_student_id WHERE $where AND p.status='VALID' GROUP BY p.currency_code",$params);$method=tuman_report_amounts($db,"SELECT p.currency_code,p.payment_method,SUM(p.amount) amount FROM tmn_payments p INNER JOIN tmn_invoices i ON i.id=p.invoice_id INNER JOIN tmn_teacher_students ts ON ts.id=i.teacher_student_id WHERE $where AND p.status='VALID' GROUP BY p.currency_code,p.payment_method",$params);$refundWhere='ts.teacher_user_id=:teacher AND r.refund_date BETWEEN :from AND :to';$refundParams=['teacher'=>$teacherId,'from'=>$f['from'],'to'=>$f['to']];if($f['assignment_id']??null){$refundWhere.=' AND r.teacher_student_id=:assignment';$refundParams['assignment']=$f['assignment_id'];}$refunds=tuman_report_amounts($db,"SELECT r.currency_code,r.refund_type,SUM(r.amount) amount FROM tmn_refunds r INNER JOIN tmn_teacher_students ts ON ts.id=r.teacher_student_id WHERE $refundWhere GROUP BY r.currency_code,r.refund_type",$refundParams);return compact('payments','method','refunds');}
function tuman_teacher_outstanding_report(PDO $db,int $teacherId,array $f): array {$sql="SELECT i.*,sp.first_name,sp.last_name,COALESCE((SELECT SUM(p.amount) FROM tmn_payments p WHERE p.invoice_id=i.id AND p.status='VALID'),0) payments,COALESCE((SELECT SUM(ca.amount) FROM tmn_credit_applications ca WHERE ca.invoice_id=i.id),0) credits,COALESCE((SELECT SUM(r.amount) FROM tmn_refunds r WHERE r.invoice_id=i.id AND r.refund_type='PAYMENT'),0) refunds FROM tmn_invoices i INNER JOIN tmn_teacher_students ts ON ts.id=i.teacher_student_id INNER JOIN tmn_student_profiles sp ON sp.user_id=ts.student_user_id WHERE ts.teacher_user_id=:teacher AND i.status IN ('ISSUED','PARTIALLY_PAID')";$params=['teacher'=>$teacherId];if($f['assignment_id']??null){$sql.=' AND i.teacher_student_id=:assignment';$params['assignment']=$f['assignment_id'];}$sql.=' ORDER BY i.invoice_date DESC,i.id DESC';return tuman_report_amounts($db,$sql,$params);}
function tuman_teacher_student_summary(PDO $db,int $teacherId,array $f): array {$sql="SELECT ts.id assignment_id,ts.status assignment_status,u.email,sp.first_name,sp.last_name,sp.phone,(SELECT COUNT(*) FROM tmn_attendance a WHERE a.teacher_student_id=ts.id AND a.session_date BETWEEN :attendance_from AND :attendance_to) attendance_count,(SELECT COUNT(*) FROM tmn_attendance a WHERE a.teacher_student_id=ts.id AND a.session_date BETWEEN :present_from AND :present_to AND a.status='PRESENT') present_count,(SELECT COUNT(*) FROM tmn_attendance a WHERE a.teacher_student_id=ts.id AND a.session_date BETWEEN :absent_from AND :absent_to AND a.status='ABSENT') absent_count FROM tmn_teacher_students ts INNER JOIN tmn_users u ON u.id=ts.student_user_id INNER JOIN tmn_student_profiles sp ON sp.user_id=u.id WHERE ts.teacher_user_id=:teacher";$params=['teacher'=>$teacherId,'attendance_from'=>$f['from'],'attendance_to'=>$f['to'],'present_from'=>$f['from'],'present_to'=>$f['to'],'absent_from'=>$f['from'],'absent_to'=>$f['to']];if($f['assignment_id']??null){$sql.=' AND ts.id=:assignment';$params['assignment']=$f['assignment_id'];}$sql.=' ORDER BY sp.first_name,sp.last_name';return tuman_report_amounts($db,$sql,$params);}
function tuman_teacher_student_currency_summary(PDO $db,int $teacherId,int $assignmentId,array $f): array {$sql="SELECT i.currency_code,COALESCE(SUM(CASE WHEN i.invoice_date BETWEEN :from AND :to THEN i.total_amount ELSE 0 END),0) invoiced,COALESCE(SUM(i.total_amount),0)-COALESCE(SUM((SELECT COALESCE(SUM(p.amount),0) FROM tmn_payments p WHERE p.invoice_id=i.id AND p.status='VALID')),0)-COALESCE(SUM((SELECT COALESCE(SUM(ca.amount),0) FROM tmn_credit_applications ca WHERE ca.invoice_id=i.id)),0)+COALESCE(SUM((SELECT COALESCE(SUM(r.amount),0) FROM tmn_refunds r WHERE r.invoice_id=i.id AND r.refund_type='PAYMENT')),0) outstanding FROM tmn_invoices i INNER JOIN tmn_teacher_students ts ON ts.id=i.teacher_student_id WHERE ts.teacher_user_id=:teacher AND i.teacher_student_id=:assignment AND i.status IN ('ISSUED','PARTIALLY_PAID','PAID') GROUP BY i.currency_code";return tuman_report_amounts($db,$sql,['teacher'=>$teacherId,'assignment'=>$assignmentId,'from'=>$f['from'],'to'=>$f['to']]);}
function tuman_admin_teachers(PDO $db): array {$s=$db->query("SELECT u.id,COALESCE(NULLIF(tp.first_name,''),u.username) first_name,tp.last_name,u.email FROM tmn_users u LEFT JOIN tmn_teacher_profiles tp ON tp.user_id=u.id WHERE u.role='TEACHER' ORDER BY first_name,last_name");return $s->fetchAll();}
function tuman_admin_teacher_summary(PDO $db,array $f,?int $teacherId): array {$sql="SELECT u.id,COALESCE(NULLIF(tp.first_name,''),u.username) first_name,tp.last_name,u.email,(SELECT COUNT(*) FROM tmn_teacher_students ts WHERE ts.teacher_user_id=u.id AND ts.status='ACTIVE') active_students,(SELECT COUNT(*) FROM tmn_teacher_students ts WHERE ts.teacher_user_id=u.id AND ts.status='INACTIVE') inactive_students FROM tmn_users u LEFT JOIN tmn_teacher_profiles tp ON tp.user_id=u.id WHERE u.role='TEACHER'";$params=[];if($teacherId){$sql.=' AND u.id=:teacher';$params['teacher']=$teacherId;}$sql.=' ORDER BY first_name,last_name';$teachers=tuman_report_amounts($db,$sql,$params);foreach($teachers as &$teacher){$income=tuman_teacher_income_report($db,(int)$teacher['id'],$f);$teacher['payments']=$income['payments'];$teacher['refunds']=$income['refunds'];$teacher['invoices']=tuman_report_amounts($db,"SELECT currency_code,COUNT(*) count,SUM(total_amount) amount FROM tmn_invoices i INNER JOIN tmn_teacher_students ts ON ts.id=i.teacher_student_id WHERE ts.teacher_user_id=:teacher AND i.invoice_date BETWEEN :from AND :to GROUP BY currency_code",['teacher'=>$teacher['id'],'from'=>$f['from'],'to'=>$f['to']]);$teacher['outstanding']=tuman_teacher_outstanding_report($db,(int)$teacher['id'],$f);}unset($teacher);return $teachers;}
function tuman_report_label(array $rows,string $amount='amount'): string {if($rows===[])return '—';$labels=[];foreach($rows as $row){$labels[]=tuman_invoice_money_label((string)$row[$amount],(string)$row['currency_code']);}return implode('<br>',$labels);}
